const items = $input.all();

// Set ke true jika ingin menguji data dummy (termasuk data bulan April 2026 di Sheet)
const MODE_TESTING = true; 

const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - (7 * 24 * 60 * 60 * 1000));

const filteredItems = [];
let totalPengeluaran = 0;
let listTeks = "";

for (const item of items) {
  const row = item.json;
  const rawDate = row.Tanggal || row.tanggal;
  if (!rawDate) continue;

  let tgl;
  // Memproses format tanggal DD/MM/YYYY
  if (typeof rawDate === 'string' && rawDate.includes('/')) {
    const parts = rawDate.split('/');
    if (parts.length === 3) {
      // Mengubah DD/MM/YYYY menjadi YYYY-MM-DD agar valid di JavaScript
      tgl = new Date(`${parts[2]}-${parts[1]}-${parts[0]}`);
    }
  } else {
    tgl = new Date(rawDate);
  }

  // Jika MODE_TESTING aktif, ambil semua data tanpa memfilter 7 hari terakhir
  const isValidDate = !isNaN(tgl.getTime());
  const isInRange = MODE_TESTING || (isValidDate && tgl >= sevenDaysAgo && tgl <= now);

  if (isInRange) {
    filteredItems.push(row);
    // Mengambil nominal dari kolom 'Jumlah (IDR)' atau 'Jumlah'
    const nominal = Number(row['Jumlah (IDR)'] || row.Jumlah || row.Nominal || 0);
    totalPengeluaran += nominal;
    listTeks += `- ${rawDate}: ${row.Kategori || 'Pengeluaran'} (${row.Deskripsi || ''}) Rp${nominal.toLocaleString('id-ID')}\n`;
  }
}

return [{
  json: {
    adaData: filteredItems.length > 0,
    jumlahTransaksi: filteredItems.length,
    totalPengeluaran: totalPengeluaran,
    promptData: listTeks || "Tidak ada transaksi",
    promptAI: `Berikut rincian pengeluaran 7 hari terakhir:\n${listTeks}\nTotal Pengeluaran: Rp${totalPengeluaran.toLocaleString('id-ID')}\n\nTulis ringkasan kebiasaan belanja saya minggu ini dan beri 1 saran penghematan konkret.`
  }
}];
